#include <stdio.h>

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1 || n < 0) return 0;
    while (n >= 10) {
        long long s = 0;
        while (n > 0) {
            s += n % 10;
            n /= 10;
        }
        n = s;
    }
    printf("%lld\n", n);
    return 0;
}

