#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    long long first = 0, second = 0, x;
    int have_first = 0, have_second = 0;
    for (int i = 0; i < n; i++) {
        if (scanf("%lld", &x) != 1) break;
        if (!have_first || x > first) {
            if (have_first) {
                second = first;
                have_second = 1;
            }
            first = x;
            have_first = 1;
        } else if (x < first && (!have_second || x > second)) {
            second = x;
            have_second = 1;
        }
    }
    if (have_second) printf("%lld\n", second);
    else puts("-1");
    return 0;
}

