#include <stdio.h>

int main(void) {
    char s[1005];
    if (scanf("%1000s", s) != 1) return 0;
    char best = s[0];
    int best_len = 1, run = 1;
    for (int i = 1; s[i] != '\0'; i++) {
        if (s[i] == s[i - 1]) run++;
        else run = 1;
        if (run > best_len) {
            best_len = run;
            best = s[i];
        }
    }
    printf("%c %d\n", best, best_len);
    return 0;
}

#include <stdio.h>

int main(void) {
    char s[1005], stack[1005];
    int top = 0, ok = 1;
    if (scanf("%1000s", s) != 1) return 0;
    for (int i = 0; s[i] != '\0' && ok; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            char open = c == ')' ? '(' : c == ']' ? '[' : '{';
            if (top == 0 || stack[top - 1] != open) ok = 0;
            else top--;
        }
    }
    puts(ok && top == 0 ? "Balanced" : "Not Balanced");
    return 0;
}
